package vista;
import elementales.Materia; import modelo.Carrera; import javax.swing.*; import javax.swing.border.*; import java.awt.*; import java.util.*; import java.util.List; import java.util.function.Consumer;
/** Malla visual con menú, progreso y simulador. */
public class VentanaPrincipal extends JFrame {
 private static final Color AZUL=new Color(45,132,184), FONDO=new Color(246,248,251); private final JComboBox<String> carreras; private final JPanel malla=new JPanel(); private final CardLayout tarjetas=new CardLayout(); private final JPanel contenido=new JPanel(tarjetas); private Consumer<String> abrir=c->{}; private Runnable simular=()->{}; private Carrera carrera; private Map<String,String> estados=Map.of();
 public VentanaPrincipal(Set<String> nombres){setTitle("Pensum Explorer | Avance Fase 2");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1440,850);setMinimumSize(new Dimension(1100,650));setLocationRelativeTo(null);setLayout(new BorderLayout());add(menu(),BorderLayout.WEST);carreras=new JComboBox<>(nombres.toArray(String[]::new));carreras.setPreferredSize(new Dimension(330,36));contenido.add(pensum(),"PENSUM");contenido.add(simulador(),"SIMULADOR");add(contenido,BorderLayout.CENTER);}
 private JPanel menu(){JPanel p=new JPanel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.setBackground(new Color(21,70,119));p.setBorder(new EmptyBorder(28,20,24,20));p.setPreferredSize(new Dimension(220,0));p.add(t("PENSUM",25,Color.WHITE));p.add(t("EXPLORER",14,new Color(185,220,245)));p.add(Box.createVerticalStrut(42));p.add(t("Fase 2 · Avance funcional",13,Color.WHITE));p.add(Box.createVerticalStrut(25));p.add(menuBoton("▣  Mi pensum",()->tarjetas.show(contenido,"PENSUM")));p.add(Box.createVerticalStrut(8));p.add(menuBoton("◈  Simulador",()->tarjetas.show(contenido,"SIMULADOR")));p.add(Box.createVerticalGlue());p.add(t("Piloto académico",12,new Color(185,220,245)));return p;}
 private JPanel pensum(){JPanel p=new JPanel(new BorderLayout(0,14));p.setBackground(FONDO);p.setBorder(new EmptyBorder(24,20,24,20));JPanel h=new JPanel(new BorderLayout(14,0));h.setOpaque(false);JPanel x=new JPanel();x.setOpaque(false);x.setLayout(new BoxLayout(x,BoxLayout.Y_AXIS));x.add(t("Mi pensum",25,new Color(28,43,57)));x.add(Box.createVerticalStrut(5));x.add(t("Selecciona una materia para consultar o registrar el avance.",13,new Color(90,102,113)));h.add(x,BorderLayout.CENTER);h.add(carreras,BorderLayout.EAST);p.add(h,BorderLayout.NORTH);malla.setBackground(FONDO);malla.setLayout(new BoxLayout(malla,BoxLayout.Y_AXIS));JScrollPane s=new JScrollPane(malla);s.setBorder(null);s.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);s.getVerticalScrollBar().setUnitIncrement(18);s.getViewport().addChangeListener(e->{int ancho=s.getViewport().getWidth();if(ancho>0&&malla.getPreferredSize().width!=ancho)malla.setPreferredSize(new Dimension(ancho,malla.getPreferredSize().height));});p.add(s,BorderLayout.CENTER);return p;}
 private JPanel simulador(){JPanel p=new JPanel();p.setBackground(FONDO);p.setBorder(new EmptyBorder(60,70,60,70));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(t("Simulador de ruta",28,new Color(28,43,57)));p.add(Box.createVerticalStrut(12));p.add(t("Calcula un orden válido. El resultado se abre en otra ventana.",14,new Color(90,102,113)));p.add(Box.createVerticalStrut(28));JButton b=new JButton("Generar simulación");b.setAlignmentX(LEFT_ALIGNMENT);b.addActionListener(e->simular.run());p.add(b);return p;}
 private JButton menuBoton(String s,Runnable r){JButton b=new JButton(s);b.setMaximumSize(new Dimension(180,38));b.setAlignmentX(LEFT_ALIGNMENT);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(Color.WHITE);b.setBackground(new Color(21,70,119));b.setBorderPainted(false);b.setFocusPainted(false);b.addActionListener(e->r.run());return b;} private JLabel t(String s,int n,Color c){JLabel l=new JLabel(s);l.setFont(new Font(Font.SANS_SERIF,Font.BOLD,n));l.setForeground(c);return l;}
 public String getCarreraSeleccionada(){return (String)carreras.getSelectedItem();} public void alCambiarCarrera(Consumer<String> c){carreras.addActionListener(e->c.accept(getCarreraSeleccionada()));} public void alAbrirMateria(Consumer<String> c){abrir=c;} public void alGenerarRuta(Runnable r){simular=r;}
 public void mostrarCarrera(Carrera c,Map<String,String> e){carrera=c;estados=e;reconstruir();} private void reconstruir(){malla.removeAll();if(carrera==null)return;for(int n=1;n<=10;n++){JPanel f=new JPanel(new BorderLayout(10,0));f.setMaximumSize(new Dimension(Integer.MAX_VALUE,118));f.setOpaque(false);f.setBorder(new EmptyBorder(5,0,7,0));JLabel l=t("Ciclo "+n,14,new Color(28,43,57));l.setPreferredSize(new Dimension(70,92));f.add(l,BorderLayout.WEST);JPanel ts=new JPanel(new GridLayout(1,5,7,7));ts.setOpaque(false);for(Materia mat:carrera.materias())if(carrera.cicloDe(mat)==n)ts.add(tarjeta(mat));f.add(ts,BorderLayout.CENTER);malla.add(f);}malla.revalidate();malla.repaint();}
 private JButton tarjeta(Materia m){String e=estados.getOrDefault(m.getCodigo(),"PENDIENTE");JButton b=new TarjetaMateria(m,e);b.setMinimumSize(new Dimension(0,0));b.setForeground(Color.WHITE);b.setBackground(color(e));b.setBorder(new LineBorder(Color.WHITE,1));b.setFocusPainted(false);b.addActionListener(x->abrir.accept(m.getCodigo()));return b;} private Color color(String e){return switch(e){case "APROBADA"->new Color(0,150,100);case "REPROBADA"->new Color(203,75,75);case "BLOQUEADA"->new Color(130,140,150);default->AZUL;};}
 private static class TarjetaMateria extends JButton { private final Materia materia; private final String estado; TarjetaMateria(Materia materia,String estado){this.materia=materia;this.estado=estado;setOpaque(true);setContentAreaFilled(true);setMargin(new Insets(0,0,0,0));} @Override protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D d=(Graphics2D)g.create();d.setColor(getForeground());d.setFont(new Font(Font.SANS_SERIF,Font.BOLD,12));d.drawString(materia.getCodigo()+" · "+materia.getUnidadesValorativas()+" UV",8,17);d.setFont(new Font(Font.SANS_SERIF,Font.BOLD,12));dibujarLineas(d,materia.getNombre(),8,40,getWidth()-16,getHeight()-54);d.setFont(new Font(Font.SANS_SERIF,Font.BOLD,10));String etiqueta=(estado.equals("BLOQUEADA")?"🔒 ":"")+estado;d.drawString(etiqueta,8,getHeight()-9);d.dispose();} private void dibujarLineas(Graphics2D d,String texto,int x,int y,int ancho,int alto){FontMetrics fm=d.getFontMetrics();StringBuilder linea=new StringBuilder();int base=y;for(String palabra:texto.split(" ")){String prueba=linea.isEmpty()?palabra:linea+" "+palabra;if(fm.stringWidth(prueba)>ancho&&!linea.isEmpty()){d.drawString(linea.toString(),x,base);base+=15;linea=new StringBuilder(palabra);if(base>y+alto) return;}else linea=new StringBuilder(prueba);}if(base<=y+alto)d.drawString(linea.toString(),x,base);} }
 public void mostrarDetalle(Materia m,boolean bloqueada,String actual,String cicloActual,DetalleGuardado guardar){JDialog d=new JDialog(this,"Detalle de asignatura",true);d.setLayout(new BorderLayout(12,12));d.setSize(440,370);d.setLocationRelativeTo(this);JPanel p=new JPanel();p.setBorder(new EmptyBorder(20,22,12,22));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(t(m.getCodigo()+" · "+m.getUnidadesValorativas()+" UV",15,AZUL));p.add(Box.createVerticalStrut(8));p.add(t(m.getNombre(),19,new Color(30,40,50)));p.add(Box.createVerticalStrut(14));p.add(new JLabel("Prerrequisitos: "+(m.getCodigoPrerequisitos().isEmpty()?"Ninguno / electiva":String.join(", ",m.getCodigoPrerequisitos()))));p.add(Box.createVerticalStrut(8));p.add(new JLabel(bloqueada?"BLOQUEADA: aprueba los prerrequisitos primero.":"Disponible para registrar avance."));p.add(Box.createVerticalStrut(16));JComboBox<String> estado=new JComboBox<>(new String[]{"PENDIENTE","APROBADA","REPROBADA"});estado.setSelectedItem(actual.equals("BLOQUEADA")?"PENDIENTE":actual);JComboBox<String> ciclo=new JComboBox<>(ciclos());if(cicloActual!=null)ciclo.setSelectedItem(cicloActual);p.add(new JLabel("Estado"));p.add(estado);p.add(new JLabel("Ciclo cursado"));p.add(ciclo);d.add(p,BorderLayout.CENTER);JPanel a=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton cancel=new JButton("Cancelar"),save=new JButton("Guardar avance");save.setEnabled(!bloqueada);cancel.addActionListener(e->d.dispose());save.addActionListener(e->{guardar.guardar((String)estado.getSelectedItem(),(String)ciclo.getSelectedItem());d.dispose();});a.add(cancel);a.add(save);d.add(a,BorderLayout.SOUTH);d.setVisible(true);}
 private String[] ciclos(){List<String> r=new ArrayList<>();for(int y=2024;y<=2031;y++){r.add("01 "+y);r.add("02 "+y);}return r.toArray(String[]::new);} public void mostrarResultado(String s){JDialog d=new JDialog(this,"Resultado de la simulación",true);JTextArea a=new JTextArea(s);a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setFont(new Font(Font.SANS_SERIF,Font.PLAIN,15));a.setBorder(new EmptyBorder(18,18,18,18));d.add(new JScrollPane(a));d.setSize(580,340);d.setLocationRelativeTo(this);d.setVisible(true);} public interface DetalleGuardado{void guardar(String estado,String ciclo);}
}
